package com.elpato.customer.presentation.home
import androidx.compose.foundation.layout.*; import androidx.compose.foundation.rememberScrollState; import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.*; import androidx.compose.runtime.*; import androidx.compose.ui.*; import androidx.compose.ui.graphics.Color; import androidx.compose.ui.text.font.FontWeight; import androidx.compose.ui.text.style.TextAlign; import androidx.compose.ui.unit.dp; import androidx.compose.ui.unit.sp; import androidx.lifecycle.viewmodel.compose.viewModel
import com.elpato.customer.ui.theme.ElPatoIcons; import com.elpato.customer.ui.theme.ElPatoTheme; import com.elpato.customer.ui.theme.Gradients; import com.elpato.customer.ui.theme.Purple600; import com.elpato.customer.ui.theme.White; import com.elpato.customer.ui.theme.Yellow500
import com.elpato.customer.presentation.common.ElPatoButton; import com.elpato.customer.presentation.common.ElPatoCard; import com.elpato.customer.presentation.common.ElPatoTopAppBar; import com.elpato.customer.presentation.common.ButtonStyle
import com.google.accompanist.permissions.rememberPermissionState; import com.google.accompanist.permissions.rememberPermissionRequired; import com.google.android.gms.maps.model.LatLng

@Composable fun HomeScreen(onBranchSelect: (String)->Unit) {
    val perm = rememberPermissionState(android.Manifest.permission.ACCESS_FINE_LOCATION); val req = rememberPermissionRequired(perm)
    androidx.compose.runtime.LaunchedEffect(Unit) { if(!perm.hasPermission) perm.launchPermissionRequest() }
    if(req) { PermissionScreen(onClick = { perm.launchPermissionRequest() }); return }
    val vm: HomeViewModel = viewModel(); val state by vm.uiState.collectAsStateWithLifecycle()
    Box(Modifier.fillMaxSize()) { Box(Modifier.fillMaxSize().background(Gradients.PrimaryToWhite))
        Column(Modifier.fillMaxSize().padding(16.dp).statusBarsPadding().verticalScroll(rememberScrollState()), horizontalAlignment = Alignment.CenterHorizontally) {
            ElPatoTopAppBar(title = "El Pato", showBack = false, actions = { IconButton(onClick={}){ Icon(ElPatoIcons.Person, "Profile", tint=White) } })
            Column(Modifier.fillMaxWidth().padding(top=32.dp, bottom=24.dp), horizontalAlignment = Alignment.CenterHorizontally) {
                androidx.compose.foundation.Image(painter = androidx.compose.ui.res.painterResource("ic_elpato_logo"), contentDescription = "Logo", modifier = Modifier.size(100.dp), colorFilter = androidx.compose.ui.graphics.ColorFilter.tint(White))
                Spacer(Modifier.height(16.dp)); Text("أقرب فرع لك", fontSize = 28.sp, fontWeight = FontWeight.Bold, color = White, textAlign = TextAlign.Center)
                Text("نحدد موقعك ونوصلك لأقرب فرع تلقائياً", fontSize = 14.sp, color = White.copy(alpha=0.8f), textAlign = TextAlign.Center)
            }
            when(state) {
                is HomeUiState.Loading -> Column(Modifier.fillMaxWidth().padding(vertical=48.dp), horizontalAlignment = Alignment.CenterHorizontally) { CircularProgressIndicator(color=White, modifier=Modifier.size(48.dp)); Spacer(Modifier.height(16.dp)); Text("جاري تحديد أقرب فرع...", color=White, fontSize=16.sp) }
                is HomeUiState.Success -> { BranchCard(state.nearest, onBranchSelect); if(state.others.isNotEmpty()){ Spacer(Modifier.height(24.dp)); Text("فروع أخرى", fontSize=20.sp, fontWeight=FontWeight.Bold, color=White).padding(bottom=12.dp); Column(Modifier.fillMaxWidth()){ state.others.forEach{ OtherBranchCard(it, onBranchSelect).padding(bottom=12.dp) } } } }
                is HomeUiState.Error -> ErrorCard(state.msg, vm::detect)
            }
        }
    }
}
@Composable fun BranchCard(b: BranchWithFee, onSelect: ()->Unit) { val can = b.deliveryFee is com.elpato.customer.domain.model.DeliveryFeeResult.Success; val feeTxt = when(b.deliveryFee){ is com.elpato.customer.domain.model.DeliveryFeeResult.Success -> "توصيل: ${it.fee} دج (${it.zoneName})"; is com.elpato.customer.domain.model.DeliveryFeeResult.OutOfRange -> "خارج نطاق التوصيل"; else -> "خطأ في حساب التوصيل" }; ElPatoCard{ Column(Modifier.padding(16.dp)){ Row(Modifier.fillMaxWidth(), Arrangement.SpaceBetween, Alignment.CenterVertically){ Column{ Text(b.branch.nameAr, fontSize=20.sp, fontWeight=FontWeight.Bold, color=Purple600); Text(b.branch.addressAr, fontSize=14.sp, color=com.elpato.customer.ui.theme.Grey700, maxLines=2) } if(b.branch.isOpen){ Badge(badgeContent={Text("مفتوح", fontSize=10.sp, color=White, fontWeight=FontWeight.Bold)}, colors=BadgeDefaults.badgeColors(containerColor=com.elpato.customer.ui.theme.SuccessGreen)){ Icon(ElPatoIcons.Storefront, "", tint=Purple600, modifier=Modifier.size(32.dp).padding(8.dp).background(Purple600.copy(alpha=0.1f), androidx.compose.foundation.shape.RoundedCornerShape(12.dp))) } } } Spacer(Modifier.height(12.dp)); Row(Modifier.fillMaxWidth(), Arrangement.SpaceBetween, Alignment.CenterVertically){ Text(feeTxt, fontSize=16.sp, fontWeight=FontWeight.Bold, color=if(can) Yellow500 else com.elpato.customer.ui.theme.ErrorRed); ElPatoButton("طلب من هذا الفرع", onSelect, enabled=can) } } } }
@Composable fun OtherBranchCard(b: Branch, onClick: ()->Unit) { ElPatoCard(onClick=onClick){ Row(Modifier.padding(16.dp).fillMaxWidth(), Arrangement.SpaceBetween, Alignment.CenterVertically){ Column{ Text(b.nameAr, fontSize=16.sp, fontWeight=FontWeight.SemiBold); Text(b.addressAr, fontSize=12.sp, color=com.elpato.customer.ui.theme.Grey700, maxLines=1) } Icon(ElPatoIcons.ChevronLeft, "", tint=com.elpato.customer.ui.theme.Grey500) } } }
@Composable fun PermissionScreen(onClick:()->Unit){ Box(Modifier.fillMaxSize().background(Gradients.PrimaryToWhite)){ Column(Modifier.fillMaxSize().padding(32.dp), Alignment.CenterHorizontally, Arrangement.Center){ Icon(ElPatoIcons.LocationOn, "", tint=White, modifier=Modifier.size(80.dp)); Spacer(Modifier.height(24.dp)); Text("نحتاج إذن الموقع", fontSize=24.sp, fontWeight=FontWeight.Bold, color=White, textAlign=TextAlign.Center); Spacer(Modifier.height(12.dp)); Text("لتحديد أقرب فرع وحساب التوصيل بدقة", fontSize=16.sp, color=White.copy(alpha=0.8f), textAlign=TextAlign.Center); Spacer(Modifier.height(32.dp)); ElPatoButton("السماح بالموقع", onClick, style=ButtonStyle.YellowAccent) } } }
@Composable fun ErrorCard(msg: String, onRetry:()->Unit){ ElPatoCard(Modifier.fillMaxWidth().padding(vertical=24.dp)){ Column(Modifier.padding(24.dp).fillMaxWidth(), Alignment.CenterHorizontally){ Icon(ElPatoIcons.ErrorOutline, "", tint=com.elpato.customer.ui.theme.ErrorRed, modifier=Modifier.size(48.dp)); Spacer(Modifier.height(16.dp)); Text(msg, fontSize=16.sp, color=com.elpato.customer.ui.theme.Grey700, textAlign=TextAlign.Center); Spacer(Modifier.height(16.dp)); ElPatoButton("إعادة المحاولة", onRetry, style=ButtonStyle.Outline) } } }
